{
 "info": {
  "title": "trimmed",
  "version": "1.0.0"
 },
 "openapi": "3.1.0",
 "paths": {
  "/v3/templates": {
   "get": {
    "parameters": [
     {
      "deprecated": false,
      "in": "header",
      "name": "on-behalf-of",
      "required": false
     },
     {
      "deprecated": false,
      "in": "query",
      "name": "generations",
      "required": false
     },
     {
      "deprecated": false,
      "in": "query",
      "name": "page_size",
      "required": true
     },
     {
      "deprecated": false,
      "in": "query",
      "name": "page_token",
      "required": false
     }
    ],
    "responses": {
     "200": {
      "content": {
       "application/json": {
        "schema": {
         "properties": {
          "_metadata": {
           "properties": {
            "count": {
             "type": "integer"
            },
            "next": {
             "type": "string"
            },
            "prev": {
             "type": "string"
            },
            "self": {
             "type": "string"
            }
           },
           "type": "object"
          },
          "result": {
           "items": {
            "properties": {
             "generation": {
              "type": "string"
             },
             "id": {
              "type": "string"
             },
             "name": {
              "type": "string"
             },
             "updated_at": {
              "type": "string"
             },
             "versions": {
              "type": "array"
             }
            },
            "required": [
             "generation",
             "id",
             "name",
             "updated_at"
            ],
            "type": "object"
           },
           "type": "array"
          }
         },
         "type": "object"
        }
       }
      }
     }
    },
    "summary": "Retrieve paged transactional templates.\n\n**This endpoint allows you to retrieve all transactional templates.**"
   }
  }
 }
}
